export const getListProjectVersionsUrl = (projectId: string,
    params?: ListProjectVersionsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `${apiBaseUrl}/api/v1/projects/${projectId}/versions?${stringifiedParams}` : `${apiBaseUrl}/api/v1/projects/${projectId}/versions`
}

